-- -- ---- Budget rates: the planned rate of the year (the first working day), dated 1 January ----
INSERT INTO public."currencyExchangeRateTable" ("rowOwnerGUID", "rowParentGUID", "orderInList", "rowJSON")
SELECT c."rowGUID",
       CASE WHEN v.kind = 'Budget' THEN v.day || '|Budget' ELSE v.day END,
       -(((v.day)::date - DATE '1970-01-01')::int),
       jsonb_build_object('startingDate', v.day, 'currencyRatio', v.ratio, 'rateType', v.kind, 'rateSource', v.source, 'rateBase', 'EUR')
  FROM (VALUES
    ('USD', '2025-01-01', 1.0321, 'Budget', 'budget-plan'),
    ('USD', '2026-01-01', 1.1721, 'Budget', 'budget-plan'),
    ('GBP', '2025-01-01', 0.83118, 'Budget', 'budget-plan'),
    ('GBP', '2026-01-01', 0.8719, 'Budget', 'budget-plan'),
    ('CHF', '2025-01-01', 0.9371, 'Budget', 'budget-plan'),
    ('CHF', '2026-01-01', 0.9296, 'Budget', 'budget-plan'),
    ('JPY', '2025-01-01', 162.04, 'Budget', 'budget-plan'),
    ('JPY', '2026-01-01', 183.94, 'Budget', 'budget-plan'),
    ('CNY', '2025-01-01', 7.5338, 'Budget', 'budget-plan'),
    ('CNY', '2026-01-01', 8.1973, 'Budget', 'budget-plan'),
    ('SEK', '2025-01-01', 11.4223, 'Budget', 'budget-plan'),
    ('SEK', '2026-01-01', 10.8085, 'Budget', 'budget-plan'),
    ('NOK', '2025-01-01', 11.7173, 'Budget', 'budget-plan'),
    ('NOK', '2026-01-01', 11.7985, 'Budget', 'budget-plan'),
    ('DKK', '2025-01-01', 7.4583, 'Budget', 'budget-plan'),
    ('DKK', '2026-01-01', 7.4694, 'Budget', 'budget-plan'),
    ('PLN', '2025-01-01', 4.2753, 'Budget', 'budget-plan'),
    ('PLN', '2026-01-01', 4.2123, 'Budget', 'budget-plan')
  ) AS v(code, day, ratio, kind, source)
  JOIN public."currencyTable" c ON upper(c."rowJSON"->>'currencyCode') = v.code
ON CONFLICT ("rowOwnerGUID", "rowParentGUID") DO UPDATE SET "orderInList" = EXCLUDED."orderInList", "rowJSON" = EXCLUDED."rowJSON", "updated_at" = now();

